import { z } from "zod";
import { data, operation, isError as isCoreError } from "@tinker/core";
import { useData, useRun } from "@tinker/react";
import { Link, Navigate, useRouterState } from "@tanstack/react-router";
import { updateTodo } from "@/transport/todos.functions";
import { readTodoChange } from "@/demo/contracts/todos-contract";
import { todos, profile } from "@/demo/frontend/state";
import { syncClient } from "~/components/sync";
import { isError } from "@/demo/errors";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card";
const flow = data<{ kind: "idle" } | { kind: "saving" } | { kind: "failed"; message: string }>({
  label: "todos.flow",
  initial: { kind: "idle" },
});
const saveTodo = operation({
  label: "todos.save",
  input: readTodoChange,
  depends: { flow: flow.controller, sync: syncClient },
  run: async ({ flow, sync }, { defer, random, input, signal }) => {
    flow.set({ kind: "saving" });
    defer(() => flow.set({ kind: "idle" }));
    const executionId = random.uuid();
    await sync.execute(
      executionId,
      { send: updateTodo, data: { executionId, change: input } },
      signal,
    );
  },
});
const showFailure = operation({
  label: "todos.showFailure",
  input(error: unknown) {
    const cause = isCoreError(error, "DataValidationFailed") ? error.payload.cause : error;
    return isError(cause, "BadInput")
      ? cause.payload.reason
      : "That change did not finish. Try again or reload the page.";
  },
  depends: { flow: flow.controller },
  run: ({ flow }, { input }) => {
    flow.set({
      kind: "failed",
      message: input,
    });
  },
});
const attemptTodo = operation({
  label: "todos.attempt",
  input: z.unknown(),
  depends: { save: saveTodo, failure: showFailure },
  run: async ({ save, failure }, { input }) => {
    const result = await save.settle({ rawInput: input });
    if (result.status === "success") return true;
    if (result.status === "failed") failure.run({ rawInput: result.error });
    else failure.run({ rawInput: undefined });
    return false;
  },
});
export function Todos() {
  const rows = useData(todos);
  const account = useData(profile);
  const loading = useRouterState({ select: (state) => state.isLoading });
  const state = useData(flow);
  const save = useRun(attemptTodo);
  const busy = state.kind === "saving" || loading;
  if (account === null) return <Navigate to="/demo" />;
  return (
    <main className="mx-auto max-w-2xl px-5 py-8 sm:py-12">
      <header className="mb-8 flex items-center justify-between gap-4">
        <div>
          <p className="text-xs font-semibold tracking-widest text-muted-foreground">
            TINKERED / TODOS
          </p>
          <p className="mt-2 break-all text-sm text-muted-foreground">
            {account.name} · {account.email}
          </p>
        </div>
        <Button asChild variant="outline">
          <Link to="/profile" disabled={busy}>
            Account
          </Link>
        </Button>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your private list</h1>
          </CardTitle>
          <CardDescription>Only you can read or change these todos.</CardDescription>
        </CardHeader>
        <CardContent>
          <form
            className="mb-5 flex items-end gap-2"
            onSubmit={async (event) => {
              event.preventDefault();
              const form = event.currentTarget;
              if (
                await save.runAsync({
                  rawInput: { kind: "add", title: new FormData(form).get("title") },
                })
              )
                form.reset();
            }}
          >
            <label className="grid min-w-0 flex-1 gap-2 text-sm font-medium">
              New todo
              <Input
                name="title"
                placeholder="What needs doing?"
                required
                maxLength={200}
                disabled={busy}
              />
            </label>
            <Button disabled={busy}>Add todo</Button>
          </form>
          <p role="alert" className="mb-3 text-sm text-destructive">
            {state.kind === "failed" ? state.message : null}
          </p>
          {rows.length === 0 ? (
            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
              Your list is empty. Add your first todo.
            </p>
          ) : (
            <ul className="divide-y">
              {rows.map((row) => (
                <li key={row.id} className="flex items-center gap-3 py-3">
                  <label className="flex min-w-0 flex-1 items-center gap-3 text-sm">
                    <input
                      type="checkbox"
                      checked={row.done}
                      disabled={busy}
                      onChange={(event) =>
                        save.runAsync({
                          rawInput: { kind: "setDone", id: row.id, done: event.target.checked },
                        })
                      }
                      className="size-4 shrink-0 accent-primary"
                    />
                    <span
                      className={
                        row.done
                          ? "min-w-0 break-words text-muted-foreground line-through"
                          : "min-w-0 break-words"
                      }
                    >
                      {row.title}
                    </span>
                  </label>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    disabled={busy}
                    aria-label={`Delete ${row.title}`}
                    onClick={() => save.runAsync({ rawInput: { kind: "delete", id: row.id } })}
                  >
                    Delete
                  </Button>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-5 text-xs text-muted-foreground">
            {rows.filter((row) => row.done).length} of {rows.length} done. Changes are saved in your
            account.
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { Todos } from "@/frontend/Todos";
export const Route = createFileRoute("/todos")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/demo" });
    await context.bootstrap();
  },
  component: Todos,
});

import { createServerFn } from "@tanstack/react-start";
import { setResponseHeader } from "@tanstack/react-start/server";

import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";

import { listTodos, changeTodo } from "@/demo/backend/todos.server";
import { readTodoCommand } from "@/demo/contracts/commands";

import { readReceipt } from "./result.server";

export const getTodos = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => {
    setResponseHeader("Cache-Control", "no-store");
    return readResult(await context.session.settle(listTodos, { signal: context.signal }));
  });

export const updateTodo = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readTodoCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(changeTodo, { input: data, signal: context.signal })),
  );

import { Link, Navigate } from "@tanstack/react-router";
import { useData, useRun } from "@tinker/react";
import type { Profile } from "@/demo/contracts/profile-contract";
import { profile, nameDraft, pending, notice, profileResult } from "@/demo/frontend/state";
import { signOut } from "./auth-actions";
import { saveName, editName, retryMail } from "./profile-actions";
import { errorText } from "./error-text";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card";
function ProfileForm({ value }: { value: Profile.Value }) {
  const draft = useData(nameDraft);
  const last = useData(profileResult);
  const retry = useRun(retryMail);
  const changeName = useRun(editName);
  const save = useRun(saveName);
  const leave = useRun(signOut);
  const busy = useData(pending);
  return (
    <form
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        save.run({ rawInput: { name: draft ?? value.name } });
      }}
    >
      <div className="flex min-w-0 items-center gap-3 rounded-lg bg-muted p-3">
        <span className="grid size-10 shrink-0 place-items-center rounded-full bg-accent font-semibold">
          {value.name.slice(0, 1).toUpperCase()}
        </span>
        <div className="min-w-0">
          <strong className="block truncate text-sm">{value.name}</strong>
          <small className="block truncate text-muted-foreground">{value.email}</small>
        </div>
        <span className="ml-auto shrink-0 text-xs text-muted-foreground">Signed in</span>
      </div>
      <label className="grid gap-2 text-sm font-medium">
        Name
        <Input
          value={draft ?? value.name}
          disabled={busy}
          onChange={(event) => changeName.run({ input: event.target.value })}
          required
          maxLength={80}
        />
      </label>
      <div className="flex gap-2">
        <Button disabled={busy}>{save.status === "pending" ? "Saving…" : "Save name"}</Button>
        <Button
          type="button"
          variant="outline"
          disabled={leave.status === "pending"}
          onClick={() => leave.run()}
        >
          {leave.status === "pending" ? "Signing out…" : "Sign out"}
        </Button>
      </div>
      {last?.result.kind === "partial" && (
        <Button
          type="button"
          variant="secondary"
          disabled={busy}
          onClick={() => retry.run({ input: last.executionId })}
        >
          Retry notification
        </Button>
      )}
      <Button asChild variant="secondary">
        <Link to="/todos" disabled={busy}>
          Open my todos
        </Link>
      </Button>
      <p role="alert" className="text-sm text-destructive">
        {errorText(save.error || leave.error)}
      </p>
    </form>
  );
}
export function ProfilePage() {
  const current = useData(profile);
  const message = useData(notice);
  if (current === null) return <Navigate to="/demo" />;
  return (
    <main className="mx-auto max-w-2xl space-y-6 px-5 py-8">
      <Link to="/demo" className="text-sm underline">
        Shared counter
      </Link>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your profile</h1>
          </CardTitle>
          <CardDescription>
            Your saved name is shared with your private list. Unsaved text stays in this editor.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ProfileForm value={current} />
          <p role="status" className="mt-3 text-sm">
            {message}
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { operation } from "@tinker/core";
import { z } from "zod";

import { syncClient } from "~/components/sync";

import { readProfileInput } from "@/demo/contracts/profile-contract";
import { raise } from "@/demo/errors";
import { nameDraft, pending, notice, profileResult } from "@/demo/frontend/state";
import { updateProfile, retryProfileNotification } from "@/transport/profile.functions";

const notificationId = z.uuid();
const draftInput = z.string();

export const saveName = operation({
  label: "saveName",
  input: readProfileInput,
  depends: {
    sync: syncClient,
    draft: nameDraft.controller,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, draft, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    notice.set("");
    defer(() => pending.set(false));

    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: updateProfile, data: { executionId, profile: input } },
      signal,
    );

    result.set({ executionId, result: completed });
    if (completed.kind === "failed") raise("WriteRejected", { message: completed.message });

    draft.set(undefined);
    notice.set(
      completed.kind === "partial"
        ? completed.notification.message
        : "Name saved and notification accepted.",
    );
  },
});

export const retryMail = operation({
  label: "retryMail",
  input: (raw: unknown) => notificationId.parse(raw),
  depends: {
    sync: syncClient,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    defer(() => pending.set(false));

    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: retryProfileNotification, data: { executionId, previousExecutionId: input } },
      signal,
    );

    result.set({ executionId, result: completed });
    notice.set(
      completed.kind === "complete"
        ? "Notification accepted. Your saved name stayed the same."
        : completed.kind === "partial"
          ? completed.notification.message
          : completed.message,
    );
  },
});

export const editName = operation({
  label: "editName",
  input: (raw: unknown) => draftInput.parse(raw),
  depends: { draft: nameDraft.controller },
  run: ({ draft }, { input }) => draft.set(input),
});

