import { ProfilePage } from "@/frontend/Profile";
export const Route = createFileRoute("/profile")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/demo" });
    await context.bootstrap();
  },
  component: ProfilePage,
});

import { createServerFn } from "@tanstack/react-start";

import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";
import { readRetry } from "~/components/sync";

import { readProfile, saveProfile, retryNotification } from "@/demo/backend/profile.server";
import { readProfileCommand } from "@/demo/contracts/commands";

import { readReceipt } from "./result.server";

export const getProfile = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) =>
    readResult(await context.session.settle(readProfile, { signal: context.signal })),
  );

export const updateProfile = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readProfileCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(saveProfile, { input: data, signal: context.signal })),
  );

export const retryProfileNotification = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readRetry)
  .handler(async ({ context, data }) =>
    readReceipt(
      await context.session.settle(retryNotification, { input: data, signal: context.signal }),
    ),
  );

import { Link } from "@tanstack/react-router";
import { useData, useRun } from "@tinker/react";

import { profile, pending, notice, authMode } from "@/demo/frontend/state";

import { signIn, setAuthMode } from "./auth-actions";
import { Counter } from "./Counter";
import { errorText } from "./error-text";
import { Button } from "./ui/button";
import { Card, CardHeader, CardTitle, CardContent } from "./ui/card";
import { Input } from "./ui/input";

function AccountForm() {
  const mode = useData(authMode);
  const changeMode = useRun(setAuthMode);
  const action = useRun(signIn);
  const busy = useData(pending);
  return (
    <form
      method="post"
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        const form = new FormData(event.currentTarget);
        action.run({
          rawInput: {
            mode,
            name: form.get("name") ?? "",
            email: form.get("email"),
            password: form.get("password"),
          },
        });
      }}
    >
      <div className="flex gap-1 rounded-lg bg-muted p-1">
        <Button
          type="button"
          variant={mode === "signup" ? "outline" : "ghost"}
          className="flex-1 text-xs"
          disabled={busy}
          aria-pressed={mode === "signup"}
          onClick={() => changeMode.run({ input: "signup" })}
        >
          Make an account
        </Button>
        <Button
          type="button"
          variant={mode === "signin" ? "outline" : "ghost"}
          className="flex-1 text-xs"
          disabled={busy}
          aria-pressed={mode === "signin"}
          onClick={() => changeMode.run({ input: "signin" })}
        >
          Sign in
        </Button>
      </div>
      {mode === "signup" && (
        <label className="grid gap-2 text-sm font-medium">
          Name
          <Input
            name="name"
            autoComplete="name"
            required
            maxLength={80}
            placeholder="Ada Lovelace"
            disabled={busy}
          />
        </label>
      )}
      <label className="grid gap-2 text-sm font-medium">
        Email
        <Input
          name="email"
          type="email"
          autoComplete="email"
          required
          placeholder="ada@example.com"
          disabled={busy}
        />
      </label>
      <label className="grid gap-2 text-sm font-medium">
        Password
        <Input
          name="password"
          type="password"
          autoComplete={mode === "signup" ? "new-password" : "current-password"}
          minLength={8}
          required
          placeholder="At least 8 characters"
          disabled={busy}
        />
      </label>
      <Button className="w-full" disabled={busy}>
        {busy ? "Working…" : mode === "signup" ? "Make account" : "Sign in"}
      </Button>
      <p role="alert" className="text-sm text-destructive">
        {errorText(action.error)}
      </p>
    </form>
  );
}

export function App() {
  const current = useData(profile);
  const message = useData(notice);
  return (
    <main className="mx-auto max-w-2xl space-y-6 px-5 py-8">
      <header>
        <p className="text-xs font-semibold tracking-widest text-muted-foreground">STARTER</p>
        <h1 className="mt-3 text-2xl font-semibold">A shared counter. Your private space.</h1>
      </header>
      <Counter />
      <Card>
        <CardHeader>
          <CardTitle>
            <h2>{current ? "Your account" : "Sign in or make an account"}</h2>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {current ? (
            <div className="flex gap-3">
              <Button asChild>
                <Link to="/profile">Open profile</Link>
              </Button>
              <Button asChild variant="outline">
                <Link to="/todos">Open private list</Link>
              </Button>
            </div>
          ) : (
            <AccountForm />
          )}
          <p role="status" className="mt-3 text-sm">
            {message}
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { operation, resource } from "@tinker/core";
import { z } from "zod";

import { syncClient, snapshotLoader } from "~/components/sync";

import { credentials } from "@/demo/contracts/credentials";
import { raise } from "@/demo/errors";
import { pending, notice, authMode } from "@/demo/frontend/state";

import { betterAuthReact } from "./modules";

const modeInput = z.enum(["signup", "signin"]);

export const authClient = resource({
  label: "browser.auth",
  depends: { auth: betterAuthReact },
  factory: async ({ auth }) => {
    const { createAuthClient } = auth;
    return createAuthClient({
      sessionOptions: { refetchInterval: 300 },
      fetchOptions: {
        onRequest(request) {
          if (
            request.method !== "POST" ||
            !new URL(request.url).pathname.endsWith("/get-session")
          ) {
            return;
          }
          request.headers.set("content-type", "application/json");
          request.body = "{}";
        },
      },
    });
  },
});

export const signIn = operation({
  label: "signIn",
  input: (raw: unknown) => {
    const parsed = credentials.safeParse(raw);
    if (!parsed.success) raise("BadInput", { reason: "Check your email and password." });
    return parsed.data;
  },
  depends: {
    client: authClient,
    sync: syncClient,
    snapshots: snapshotLoader,
    pending: pending.controller,
    notice: notice.controller,
  },
  run: async ({ client, sync, snapshots, pending, notice }, { defer, input, signal, log }) => {
    pending.set(true);
    notice.set("");
    defer(() => pending.set(false));

    const change = snapshots.beginAccountChange();
    defer(() => snapshots.endAccountChange(change));
    sync.leave();

    const result =
      input.mode === "signup"
        ? await client.signUp.email(input, { signal: signal })
        : await client.signIn.email(input, { signal: signal });
    if (result.error) raise("AuthFailed", { message: result.error.message ?? "Sign in failed." });

    await snapshots.completeAccountChange(signal, change);
    notice.set("You are signed in. Open your profile or private list.");
    log("account.signedIn");
  },
});

export const signOut = operation({
  label: "signOut",
  depends: { client: authClient, sync: syncClient, notice: notice.controller },
  run: async ({ client, sync, notice }, { signal }) => {
    const result = await client.signOut({ fetchOptions: { signal: signal } });
    if (result.error) raise("AuthFailed", { message: result.error.message ?? "Sign out failed." });
    sync.leave();
    notice.set("You are signed out. Committed changes remain saved.");
  },
});

export const setAuthMode = operation({
  label: "setAuthMode",
  input: (raw: unknown) => modeInput.parse(raw),
  depends: { mode: authMode.controller },
  run: ({ mode }, { input }) => mode.set(input),
});

import { operation } from "@tinker/core";
import { useData, useRun } from "@tinker/react";

import { syncClient } from "~/components/sync";

import { counter } from "@/demo/frontend/state";
import { updateCounter } from "@/transport/counter.functions";

import { Button } from "./ui/button";
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from "./ui/card";

const increase = operation({
  label: "counter.increase",
  depends: { sync: syncClient },
  run: async ({ sync }, { random, signal }) => {
    const executionId = random.uuid();
    await sync.execute(executionId, { send: updateCounter, data: { executionId } }, signal);
  },
});

export function Counter() {
  const value = useData(counter);
  const action = useRun(increase);
  return (
    <Card>
      <CardHeader>
        <CardTitle>
          <h2>Shared counter</h2>
        </CardTitle>
        <CardDescription>Everyone can add one. No sign-in needed.</CardDescription>
      </CardHeader>
      <CardContent className="flex items-center justify-between gap-4">
        <output aria-label="Counter value" className="text-3xl font-semibold tabular-nums">
          {value}
        </output>
        <Button disabled={action.status === "pending"} onClick={() => action.run()}>
          {action.status === "pending" ? "Waiting for sync…" : "Increase counter"}
        </Button>
        {Boolean(action.error) && (
          <p role="alert" className="text-sm">
            The counter did not finish. Try again.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

